/**
 * Install trees outside the workspace, for the gates that compare boat with
 * the official release. A vanilla tree is dsh exactly as npm publishes it; a
 * boat tree is the same manifest with every kernel package replaced by boat's
 * packed build (`packKernel`), the way a consumer of a private registry would
 * receive it. Both pin every dsh and cordis package to `dsh.upstream.json` and
 * hoist `@deepseek-ai/*` like the workspace does, so bare row names resolve.
 * Trees live under `$BOAT_DIST_CACHE` (default `~/.cache/boat-dist`), never
 * inside the repository, so Node's upward lookup cannot fall back to the
 * workspace's own node_modules.
 * @module scripts/dist/trees
 */

import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { stringify } from 'yaml'
import { git, kernelPackages, readUpstreamPin, repoRoot } from './kernel.ts'

export const distCache = process.env['BOAT_DIST_CACHE'] ?? join(homedir(), '.cache', 'boat-dist')

/** A dsh release as a tree pins it: the dsh version and the cordis versions its tag vendors. */
export interface DshRelease {
  dsh: string
  cordis: Record<string, string>
}

/** What a tree installs: the release it pins, dependencies by spec, and overrides applied to the whole graph. */
export interface TreeSpec {
  release: DshRelease
  dependencies: Record<string, string>
  overrides?: Record<string, string>
}

/** The release `dsh.upstream.json` pins. */
export function pinnedRelease(): DshRelease {
  const { dsh, cordis } = readUpstreamPin()
  return { dsh, cordis }
}

/** The release a dsh checkout is at: its root version and its `vendor/*` package versions. */
export function releaseOfCheckout(checkout: string): DshRelease {
  const read = (path: string): { name: string; version: string } => JSON.parse(readFileSync(path, 'utf8')) as { name: string; version: string }
  const cordis: Record<string, string> = {}
  for (const entry of readdirSync(join(checkout, 'vendor'))) {
    const path = join(checkout, 'vendor', entry, 'package.json')
    if (!existsSync(path)) continue
    const { name, version } = read(path)
    cordis[name] = version
  }
  return { dsh: read(join(checkout, 'package.json')).version, cordis }
}

const PACKAGE_MANAGER = (JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8')) as { packageManager: string }).packageManager

/**
 * The pnpmfile every tree gets: the same pinning boat's workspace does, except
 * for overridden names, whose override must win over the pin.
 */
function pnpmfile(release: DshRelease, overridden: readonly string[]): string {
  return `// Generated by scripts/dist/trees.ts.
const dsh = ${JSON.stringify(release.dsh)}
const cordis = ${JSON.stringify(release.cordis)}
const overridden = new Set(${JSON.stringify(overridden)})
function pinned(name) {
  if (overridden.has(name)) return undefined
  if (name === '@deepseek-ai/dsh' || name.startsWith('@deepseek-ai/dsh-')) return dsh
  return cordis[name]
}
function pin(deps) {
  if (!deps) return
  for (const name of Object.keys(deps)) {
    const version = pinned(name)
    if (version !== undefined) deps[name] = version
  }
}
module.exports = { hooks: { readPackage(pkg) { pin(pkg.dependencies); pin(pkg.optionalDependencies); pin(pkg.peerDependencies); return pkg } } }
`
}

/**
 * Install `spec` into `dir` unless the same spec is already installed there.
 * @returns the tree directory.
 */
export function installTree(dir: string, spec: TreeSpec): string {
  const manifest = { name: 'boat-dist-tree', private: true, type: 'module', packageManager: PACKAGE_MANAGER, dependencies: spec.dependencies }
  const overrides = spec.overrides ?? {}
  const workspace = {
    packages: [],
    // A tree installs the release boat pins, published within the last day or not.
    minimumReleaseAge: 0,
    publicHoistPattern: ['@deepseek-ai/*'],
    overrides,
    allowBuilds: { '@deepseek-ai/dsh-subprocess-local': true, esbuild: true, 'node-pty': false, koffi: false, '@google/genai': false, protobufjs: false },
  }
  const files = {
    'package.json': `${JSON.stringify(manifest, null, 2)}\n`,
    'pnpm-workspace.yaml': stringify(workspace),
    '.pnpmfile.cjs': pnpmfile(spec.release, Object.keys(overrides)),
  }
  const key = createHash('sha256').update(JSON.stringify(files)).update(overrideDigests(overrides)).digest('hex')
  const stamp = join(dir, '.boat-dist-tree')
  if (existsSync(stamp) && readFileSync(stamp, 'utf8') === key) return dir
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  for (const [name, text] of Object.entries(files)) writeFileSync(join(dir, name), text)
  execFileSync('pnpm', ['install', '--no-frozen-lockfile', '--reporter=append-only'], { cwd: dir, stdio: ['ignore', 'inherit', 'inherit'] })
  writeFileSync(stamp, key)
  return dir
}

/** Content digests of `file:` tarball overrides, so a repacked kernel reinstalls the tree. */
function overrideDigests(overrides: Record<string, string>): string {
  return Object.values(overrides)
    .filter(spec => spec.startsWith('file:') && spec.endsWith('.tgz'))
    .map(spec => createHash('sha256').update(readFileSync(spec.slice('file:'.length))).digest('hex'))
    .join(',')
}

/** A tree of the official release: the dsh CLI, the kernel packages, and `extra`. */
export function vanillaTree(name: string, extra: Record<string, string> = {}, release = pinnedRelease()): string {
  const kernel = Object.fromEntries(kernelPackages().map(({ name: pkg }) => [pkg, release.dsh]))
  return installTree(join(distCache, `vanilla-${release.dsh}-${name}`), {
    release,
    dependencies: { '@deepseek-ai/dsh': release.dsh, ...kernel, ...extra },
  })
}

/** The same tree with every kernel package taken from boat's packs (see `packKernel`). */
export function boatTree(name: string, packs: Record<string, string>, extra: Record<string, string> = {}): string {
  const release = pinnedRelease()
  const overrides = Object.fromEntries(Object.entries(packs).map(([pkg, file]) => [pkg, `file:${file}`]))
  return installTree(join(distCache, `boat-${release.dsh}-${name}`), {
    release,
    dependencies: { '@deepseek-ai/dsh': release.dsh, ...overrides, ...extra },
    overrides,
  })
}

/**
 * Pack every built kernel package as npm would publish it, with the version
 * stamped `<upstream>+boat.<commit>`. Build metadata is ignored by semver range
 * matching, so every peer range written against the upstream version still
 * matches, while the installed manifest says it is boat's build.
 * @returns package name → tarball path.
 */
export function packKernel(): Record<string, string> {
  const commit = git(repoRoot, ['rev-parse', '--short=10', 'HEAD'])
  const out = join(distCache, 'packs', commit)
  rmSync(out, { recursive: true, force: true })
  mkdirSync(out, { recursive: true })
  const packs: Record<string, string> = {}
  for (const { name, dir } of kernelPackages()) {
    const packageDir = join(repoRoot, 'dsh', dir)
    if (!existsSync(join(packageDir, 'lib'))) throw new Error(`${name}: dsh/${dir}/lib is missing; run pnpm run build first`)
    const scratch = mkdtempSync(join(out, 'pack-'))
    execFileSync('pnpm', ['pack', '--pack-destination', scratch], { cwd: packageDir, stdio: ['ignore', 'ignore', 'inherit'] })
    const [tarball] = readdirSync(scratch).filter(file => file.endsWith('.tgz'))
    if (tarball === undefined) throw new Error(`${name}: pnpm pack wrote no tarball`)
    execFileSync('tar', ['-xzf', tarball], { cwd: scratch })
    const manifestPath = join(scratch, 'package', 'package.json')
    const manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as { version: string }
    manifest.version = `${manifest.version}+boat.${commit}`
    writeFileSync(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`)
    const target = join(out, `${name.replace('@', '').replace('/', '-')}.tgz`)
    execFileSync('tar', ['-czf', target, 'package'], { cwd: scratch })
    rmSync(scratch, { recursive: true, force: true })
    packs[name] = target
  }
  return packs
}

